```python
import random

def get_user_guess():
    """Get a valid integer user guess."""
    while True:
        try:
            guess = int(input("Guess a number between 1 and 100: "))
            if 1 <= guess <= 100:
                return guess
            else:
                print("Your guess must be between 1 and 100. Please try again.")
        except ValueError:
            print("That's not a valid integer. Please try again.")

def play_game():
    """Play the number guessing game."""
    random_number = random.randint(1, 100)
    user_guess = get_user_guess()

    while user_guess != random_number:
        if user_guess < random_number:
            print("Too high!")
        elif user_guess > random_number:
            print("Too low!")
        user_guess = get_user_guess()

    print(f"Congratulations! You guessed the number {random_number} correctly.")

if __name__ == "__main__":
    play_game()
```

This program will generate a random number and prompt the user to guess it. The user will receive hints based on whether their guess is too high, too low, or correct.
